<h1 class="h3 mb-1">Verwaltung</h1><p class="lead"><?=h($locationName)?></p>
<div class="d-flex flex-wrap gap-2 mb-4"><a class="btn btn-outline-success" href="/<?=h($location)?>/admin/export?sig=<?=rawurlencode($sig)?>">Excel herunterladen</a><form method="post" action="/<?=h($location)?>/admin/delete-all" onsubmit="return confirm('Wirklich alle Anmeldungen für <?=h($locationName)?> löschen? Dieser Vorgang kann nicht rückgängig gemacht werden.')"><input type="hidden" name="_csrf" value="<?=h($app->csrf())?>"><input type="hidden" name="sig" value="<?=h($sig)?>"><button class="btn btn-outline-danger">Alle löschen</button></form></div>
